create table if not exists public.content_publication_claims(candidate_id uuid primary key references public.ai_generated_candidates(id) on delete cascade,status text not null default 'processing' check(status in ('processing','completed')),result_payload jsonb,started_at timestamptz not null default now(),completed_at timestamptz);
alter table public.content_publication_claims enable row level security;create policy content_publication_claims_admin on public.content_publication_claims for select using(public.is_platform_admin());
create or replace function public.claim_content_publication(p_candidate_id uuid) returns table(claimed boolean,status text,result_payload jsonb) language plpgsql security definer set search_path=public as $$declare v public.content_publication_claims%rowtype;begin if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then raise exception 'service role required' using errcode='42501';end if;insert into public.content_publication_claims(candidate_id)values(p_candidate_id)on conflict do nothing returning * into v;if found then return query select true,v.status,v.result_payload;return;end if;select * into v from public.content_publication_claims where candidate_id=p_candidate_id for update;return query select false,v.status,v.result_payload;end;$$;
create or replace function public.finish_content_publication(p_candidate_id uuid,p_result jsonb)returns void language plpgsql security definer set search_path=public as $$begin if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then raise exception 'service role required' using errcode='42501';end if;update public.content_publication_claims set status='completed',result_payload=p_result,completed_at=now()where candidate_id=p_candidate_id and status='processing';if not found then raise exception 'publication claim missing';end if;end;$$;
revoke all on function public.claim_content_publication(uuid),public.finish_content_publication(uuid,jsonb) from public,anon,authenticated;grant execute on function public.claim_content_publication(uuid),public.finish_content_publication(uuid,jsonb) to service_role;
